interface Want {
  item: string;
  qty: number;
}

export interface FulfillmentResult {
  ok: boolean;
  error?: string;
  orders?: Record<string, string>;
  stock?: Record<string, number>;
  queue?: string[];
  rejected?: number;
  report?: string;
}

type Event = Record<string, unknown>;

/** Mutable state threaded through every event handler. */
interface State {
  stock: Record<string, number>;
  orders: Record<string, string>;
  reserved: Record<string, Want>;
  pendingWants: Record<string, Want>;
  queue: string[];
  rejected: number;
}

const onHand = (stock: Record<string, number>, item: string): number =>
  stock[item] === undefined ? 0 : stock[item];

const badEvent = (index: number, reason: string): string =>
  "event " + index + ": " + reason;

// --- field validation: return a bad-event message, or undefined when the field is present ---
const requireId = (event: Event, index: number): string | undefined =>
  typeof event.id !== "string" || event.id.length === 0 ? badEvent(index, "bad id") : undefined;

const requireItem = (event: Event, index: number): string | undefined =>
  typeof event.item !== "string" || event.item.length === 0 ? badEvent(index, "bad item") : undefined;

const requireQty = (event: Event, index: number): string | undefined =>
  !Number.isInteger(event.qty) || (event.qty as number) < 1 ? badEvent(index, "bad qty") : undefined;

const requireOptionalQty = (event: Event, index: number): string | undefined =>
  event.qty !== undefined && (!Number.isInteger(event.qty) || (event.qty as number) < 1)
    ? badEvent(index, "bad qty")
    : undefined;

/** Release freed stock into backordered orders in FIFO order. */
function fulfillBackorders(state: State): void {
  for (let position = 0; position < state.queue.length; position++) {
    const id = state.queue[position];
    const want = state.pendingWants[id];
    if (onHand(state.stock, want.item) >= want.qty) {
      state.stock[want.item] = onHand(state.stock, want.item) - want.qty;
      state.reserved[id] = { item: want.item, qty: want.qty };
      state.orders[id] = "reserved";
      delete state.pendingWants[id];
      state.queue.splice(position, 1);
      position = position - 1;
    }
  }
}

function onOrder(state: State, index: number, event: Event): string | undefined {
  const err =
    requireId(event, index) ||
    requireItem(event, index) ||
    requireQty(event, index);
  if (err) return err;
  if (state.orders[event.id as string] !== undefined) return badEvent(index, "duplicate order");
  const item = event.item as string;
  const qty = event.qty as number;
  if (onHand(state.stock, item) >= qty) {
    state.stock[item] = onHand(state.stock, item) - qty;
    state.reserved[event.id as string] = { item, qty };
    state.orders[event.id as string] = "reserved";
  } else {
    state.queue.push(event.id as string);
    state.pendingWants[event.id as string] = { item, qty };
    state.orders[event.id as string] = "backordered";
  }
}

function onCancel(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "cancelled";
    fulfillBackorders(state);
  } else if (state.orders[id] === "backordered") {
    state.queue.splice(state.queue.indexOf(id), 1);
    delete state.pendingWants[id];
    state.orders[id] = "cancelled";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function onShip(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index) || requireOptionalQty(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] === undefined) {
    state.rejected = state.rejected + 1;
  } else if (event.qty === undefined || (event.qty as number) === state.reserved[id].qty) {
    delete state.reserved[id];
    state.orders[id] = "shipped";
  } else if ((event.qty as number) < state.reserved[id].qty) {
    state.reserved[id].qty = state.reserved[id].qty - (event.qty as number);
    state.orders[id] = "partial";
  } else {
    state.rejected = state.rejected + 1;
  }
}

function onRestock(state: State, index: number, event: Event): string | undefined {
  const err = requireItem(event, index) || requireQty(event, index);
  if (err) return err;
  state.stock[event.item as string] = onHand(state.stock, event.item as string) + (event.qty as number);
  fulfillBackorders(state);
}

function onExpire(state: State, index: number, event: Event): string | undefined {
  const err = requireId(event, index);
  if (err) return err;
  const id = event.id as string;
  if (state.reserved[id] !== undefined) {
    const holding = state.reserved[id];
    state.stock[holding.item] = onHand(state.stock, holding.item) + holding.qty;
    delete state.reserved[id];
    state.orders[id] = "expired";
    fulfillBackorders(state);
  } else {
    state.rejected = state.rejected + 1;
  }
}

const HANDLERS: Record<string, (state: State, index: number, event: Event) => string | undefined> = {
  order: onOrder,
  cancel: onCancel,
  ship: onShip,
  restock: onRestock,
  expire: onExpire,
};

export function processEvents(raw: unknown): FulfillmentResult {
  if (typeof raw !== "object" || raw === null) {
    return { ok: false, error: "malformed input" };
  }
  const input = raw as Record<string, unknown>;
  if (typeof input.stock !== "object" || input.stock === null) {
    return { ok: false, error: "bad stock" };
  }
  const stock: Record<string, number> = {};
  const rawStock = input.stock as Record<string, unknown>;
  for (const item of Object.keys(rawStock)) {
    if (!Number.isInteger(rawStock[item]) || (rawStock[item] as number) < 0) {
      return { ok: false, error: "bad stock" };
    }
    stock[item] = rawStock[item] as number;
  }
  if (!Array.isArray(input.events)) {
    return { ok: false, error: "bad events" };
  }

  const state: State = {
    stock,
    orders: {},
    reserved: {},
    pendingWants: {},
    queue: [],
    rejected: 0,
  };

  for (let index = 0; index < input.events.length; index++) {
    const event = input.events[index] as Event;
    if (typeof event !== "object" || event === null) {
      return { ok: false, error: badEvent(index, "malformed") };
    }
    const handle = HANDLERS[event.type as string];
    if (handle === undefined) {
      return { ok: false, error: badEvent(index, "bad type") };
    }
    const err = handle(state, index, event);
    if (err) {
      return { ok: false, error: err };
    }
  }

  return {
    ok: true,
    orders: state.orders,
    stock: state.stock,
    queue: state.queue,
    rejected: state.rejected,
    report: buildReport(state.orders, state.rejected),
  };
}

const STATUSES = ["reserved", "backordered", "shipped", "partial", "cancelled", "expired"];

function statusCounts(orders: Record<string, string>): Record<string, number> {
  const counts: Record<string, number> = {};
  for (const status of STATUSES) {
    counts[status] = 0;
  }
  for (const id of Object.keys(orders)) {
    counts[orders[id]] = counts[orders[id]] + 1;
  }
  return counts;
}

function buildReport(orders: Record<string, string>, rejected: number): string {
  const counts = statusCounts(orders);
  let line = "orders=" + Object.keys(orders).length;
  for (const status of STATUSES) {
    line = line + ";" + status + "=" + counts[status];
  }
  return line + ";rejected=" + rejected;
}

